var bad = []
for f in TerrainManager.terrain_features:
	var id = str(f.get("id", ""))
	var icon = node.get_node_or_null("Main/BoardRoot/TerrainCoverOverlay/TerrainCoverIcon_" + id)
	if icon == null:
		bad.append(id + ": no icon")
		continue
	var poly = f.get("polygon", PackedVector2Array())
	var a2 = 0.0
	var acc = Vector2.ZERO
	for i in range(poly.size()):
		var p = poly[i]
		var q = poly[(i + 1) % poly.size()]
		var cr = p.x * q.y - q.x * p.y
		a2 += cr
		acc += (p + q) * cr
	var d = icon.position.distance_to(acc / (3.0 * a2))
	if d > 8.0:
		bad.append("%s: %.1fpx from its polygon centroid" % [id, d])
return bad

var bad = []
for f in TerrainManager.terrain_features:
	var id = str(f.get("id", ""))
	var icon = node.get_node_or_null("Main/BoardRoot/TerrainCoverOverlay/TerrainCoverIcon_" + id)
	if icon == null or icon.modulate.a < 0.8:
		bad.append(id)
return bad

var legend = {"exposed": "+1", "light": "+2", "dense": "LB"}
var bad = []
for f in TerrainManager.terrain_features:
	var id = str(f.get("id", ""))
	var icon = node.get_node_or_null("Main/BoardRoot/TerrainCoverOverlay/TerrainCoverIcon_" + id)
	var text = "<no icon>" if icon == null else icon.get_node("Label").text
	var want = TerrainManager.cover_type_of(f)
	if text != want or text != legend.get(str(f.get("category", "")), "?"):
		bad.append("%s: label %s, cover_type %s, category %s" % [id, text, want, str(f.get("category", ""))])
return bad

var seen = {}
for c in node.get_node("Main/BoardRoot/TerrainCoverOverlay").get_children():
	seen[c.get_node("Label").text] = true
return seen.size()

var ov = node.get_node("Main/BoardRoot/TerrainCoverOverlay")
for t in node.get_node("Main/BoardRoot/TokenLayer").get_children():
	if "base_shape" in t:
		return ov.z_index < t.z_index
return false

var lg = node.get_node("Main")._settings_menu.find_child("TerrainCoverLegend", true, false)
var sc = lg.get_parent()
while sc != null and not (sc is ScrollContainer):
	sc = sc.get_parent()
sc.ensure_control_visible(lg)
return sc != null

var bad = []
for c in node.get_node("Main/BoardRoot/TerrainCoverOverlay").get_children():
	if not c.is_visible_in_tree() or c.modulate.a < 0.8:
		bad.append(str(c.name))
return bad

var bad = []
for c in node.get_node("Main/BoardRoot/TerrainCoverOverlay").get_children():
	var xf = c.get_global_transform_with_canvas()
	if absf(xf.get_scale().x - 1.0) > 0.02 or absf(xf.get_rotation()) > 0.01:
		bad.append("%s: on-screen scale %.3f, rotation %.3f" % [c.name, xf.get_scale().x, xf.get_rotation()])
return bad

var n = 0
for t in node.get_node("Main/BoardRoot/TokenLayer").get_children():
	if ("base_shape" in t) and t.base_shape != null and t.visible:
		n += 1
return n

var ov = node.get_node("Main/BoardRoot/TerrainCoverOverlay")
var hits = []
for icon in ov.get_children():
	var half = Vector2(TerrainCoverOverlay.ICON_WIDTH, TerrainCoverOverlay.ICON_HEIGHT) * 0.5 * icon.scale.x
	var r = Rect2(icon.position - half, half * 2.0)
	var corners = [r.position, Vector2(r.end.x, r.position.y), r.end, Vector2(r.position.x, r.end.y)]
	for t in node.get_node("Main/BoardRoot/TokenLayer").get_children():
		if not ("base_shape" in t) or t.base_shape == null or not t.visible:
			continue
		var rot = float(t.model_data.get("rotation", 0.0))
		var hit = r.has_point(t.position) or t.base_shape.contains_point(icon.position, t.position, rot)
		for i in range(4):
			if hit:
				break
			hit = t.base_shape.overlaps_with_segment(t.position, rot, corners[i], corners[(i + 1) % 4])
		if hit:
			hits.append("%s x %s" % [icon.name, str(t.model_data.get("id", t.name))])
return hits

